var GROUPS=[{id:"pay",label:"Pay",subs:[["pay","Salary","owner"],["payrep","Pay report"]]},{id:"cash",label:"Cash",subs:[["book","Book"],["cash","Cash flow"]]},{id:"day",label:"Day",subs:[["dayrep","Day report"],["recon","Reconcile"],["exp","Expenses"]]},{id:"tankg",label:"Tanks",subs:[["tanks","Tanks"],["atg","ATG stock"]]},{id:"checks",label:"Checks",subs:[["dreq","Daily required"],["lic","Licences"]]},{id:"reports",label:"Reports",subs:[["rep","Reports"],["reg","Registers"]]}];
function groupOf(t){for(var i=0;i<GROUPS.length;i++){if(GROUPS[i].subs.some(function(s){return s[0]==t}))return GROUPS[i]}return null}
function groupSubs(g){return g.subs.filter(function(s){return !(s[2]=="owner"&&!(ME&&ME.role=="owner"))})}
function mergeTiles(T){var keys=T.map(function(t){return t[0]}),out=[],used={};
T.forEach(function(t){var g=groupOf(t[0]);if(!g){out.push(t);return}if(used[g.id])return;var subs=groupSubs(g).filter(function(s){return keys.indexOf(s[0])>=0});if(!subs.length)return;used[g.id]=1;out.push([subs[0][0],g.label])});return out}
