function meterGroups(M){return M.fuels.map(function(f){return{fuel:f,list:M.nozzles.filter(function(n){return n.fuel==f})}}).filter(function(g){return g.list.length})}
function meterNote(R){if(!R.meter||!R.meter.nozzles.length)return "";var bad=R.meter.rows.filter(function(r){var b=r.byFuel&&r.byFuel[R.fuel];return b&&b.check!=0}).length;return bad?'<div class="sub" style="color:var(--due);margin-bottom:8px">Sales by meter come from the Meter register (all products). '+bad+' day'+(bad>1?'s differ':' differs')+' from the duty figures for '+esc(R.fuel)+': see the Meter register.</div>':'<div class="sub" style="margin-bottom:8px">Sales by meter come from the Meter register (all products) and match the duty figures for '+esc(R.fuel)+' on every day.</div>'}
function meterHtml(R){var M=R.meter;if(!M||!M.nozzles.length)return '<div class="empty">No nozzles yet. Add them in Pump setup.</div>';
var G=meterGroups(M),cols=[];G.forEach(function(g){g.list.forEach(function(n){cols.push(n)})});
var h='<h1 style="text-align:center;background:#f4b400;color:#1a1a1a;padding:6px;border-radius:6px">All products \u00b7 meter register \u00b7 '+R.month+'</h1><div class="sub">One register for every tank and product, grouped by product. Each day shows the last pump reading and the sale since the day before. A nozzle starts from the opening meter set in Pump setup on the day it was added. Check is the sale minus the duty readings (closing minus opening): 0 means they agree.</div>';
var w=220+cols.length*150+M.fuels.length*120;
h+='<div class="tbl" style="margin-top:8px"><table style="min-width:'+w+'px;font-size:13px"><tr><th rowspan="2">Date</th>'+G.map(function(g){return '<th colspan="'+(2*g.list.length)+'" style="text-align:center">'+esc(g.fuel)+'</th>'}).join("")+'<th colspan="'+M.fuels.length+'" style="text-align:center">Sale by product</th><th rowspan="2" class="r">Check</th></tr><tr>'+cols.map(function(n){return '<th class="r">'+esc(n.name)+' reading</th><th class="r">'+esc(n.name)+' sale</th>'}).join("")+M.fuels.map(function(f){return '<th class="r">'+esc(f)+'</th>'}).join("")+'</tr>';
var tot={};cols.forEach(function(n){tot[n.id]=0});var pt={};M.fuels.forEach(function(f){pt[f]=0});
M.rows.forEach(function(r){var empty=cols.every(function(n){return !r.cells[n.id]});var ck=0;M.fuels.forEach(function(f){ck=rnd(ck+(r.byFuel[f]?r.byFuel[f].check:0))});var bad=ck!=0;
h+='<tr'+(empty?' style="opacity:.4"':'')+'><td>'+fdt(r.d)+'</td>'+cols.map(function(n){var c=r.cells[n.id];if(c)tot[n.id]=rnd(tot[n.id]+c.sales);return '<td class="r">'+(c?rnd(c.reading):'')+'</td><td class="r"'+(c&&c.check!=0?' style="color:var(--due);font-weight:700"':'')+'>'+(c?rnd(c.sales):'')+'</td>'}).join("")+M.fuels.map(function(f){var b=r.byFuel[f];pt[f]=rnd(pt[f]+(b?b.sales:0));return '<td class="r">'+(b&&b.sales?rnd(b.sales):'')+'</td>'}).join("")+'<td class="r"'+(bad?' style="color:var(--due);font-weight:700"':'')+'>'+(bad?rnd(ck):'0')+'</td></tr>'});
h+='<tr><td><b>Total</b></td>'+cols.map(function(n){return '<td></td><td class="r"><b>'+rnd(tot[n.id])+'</b></td>'}).join("")+M.fuels.map(function(f){return '<td class="r"><b>'+rnd(pt[f])+'</b></td>'}).join("")+'<td></td></tr></table></div>';
return h}
