h+=sect("Pay shortage this month");if(D.payShortage.length){var PS=D.payShortage,tot=function(k){return PS.reduce(function(a,x){return a+x[k]},0)};h+=rtab("Worker shortages",["Worker","Short duties","Short","Waived","Deducted from pay"],PS.map(function(x){return[esc(x.name),x.count,m2(x.short),m2(x.waived),'<b style="color:'+(x.deducted?'var(--due)':'var(--ok)')+'">'+m2(x.deducted)+'</b>']}).concat([["<b>Total</b>",tot("count"),"<b>"+m2(tot("short"))+"</b>","<b>"+m2(tot("waived"))+"</b>","<b>"+m2(tot("deducted"))+"</b>"]]))}else h+='<div class="cust" style="cursor:default"><div class="sub">No worker is short this month.</div></div>';
