// ---- Book: one book per payment mode (Bank is its own book). Older entries map to the right book automatically.
function bookList(){var L=allModes().filter(function(m){return m.active!==false||m.key=="cash"}).map(function(m){return{key:m.key,name:m.name}});if(!L.some(function(m){return m.key=="bank"}))L.push({key:"bank",name:"Bank"});return L}
function bkeyOf(name){if(name==null||name==="")return "cash";var n=String(name).trim().toLowerCase();if(n=="cash")return "cash";if(n=="upi"||n=="upi / wallet"||n=="wallet")return "upi";if(["bank","bank transfer","cheque","neft","rtgs","imps"].indexOf(n)>=0)return "bank";var m=allModes().filter(function(x){return String(x.name).toLowerCase()==n||x.key==n})[0];return m?m.key:(n=="card"?"card":"other")}
function bookName(k){var b=bookList().filter(function(x){return x.key==k})[0];return b?b.name:(k=="other"?"Other":String(k))}
function obOf(k){var o=S.ob||{};if(o[k]!=null)return +o[k]||0;var legacy={cash:"Cash",bank:"Bank",upi:"UPI"}[k];return legacy&&o[legacy]!=null?(+o[legacy]||0):0}
function bkRows(){var r=[];
(DM||[]).forEach(function(x){var by={};Object.keys(x.pay).forEach(function(k){var amt=+x.pay[k]||0;if(amt<=0)return;var bk=allModes().some(function(m){return m.key==k})?k:bkeyOf(k);by[bk]=(by[bk]||0)+amt});Object.keys(by).forEach(function(bk){r.push({d:x.d,a:bk,m:rnd(by[bk]),n:"Duty collections "+x.d})})});
S.c.forEach(function(c){c.e.forEach(function(x){if(x.t=="pay")r.push({d:x.d,a:bkeyOf(x.n),m:+x.a,n:"Received from "+c.name})})});
(S.shop||[]).forEach(function(x){r.push({d:x.d,a:x.mode,m:x.total,n:"Shop sale: "+x.lines.map(function(l){return l.name+" x"+l.qty}).join(", ")})});
S.sup.forEach(function(s){s.e.forEach(function(x){if(x.t=="pay")r.push({d:x.d,a:bkeyOf(x.n),m:-x.a,n:"Paid to "+s.name})})});
S.bk.forEach(function(b){
 if(b.dep){r.push({d:b.d,a:"cash",m:-b.a,n:"Bank deposit"+(b.slip?" (slip "+b.slip+")":"")+(b.by?" by "+b.by:""),id:b.id});r.push({d:b.d,a:"bank",m:b.a,n:"Bank deposit received",id:b.id});return}
 if(b.t=="xfer"){r.push({d:b.d,a:bkeyOf(b.acct),m:-b.a,n:"Transfer to "+bookName(bkeyOf(b.to)),id:b.id});r.push({d:b.d,a:bkeyOf(b.to),m:b.a,n:"Transfer from "+bookName(bkeyOf(b.acct)),id:b.id});return}
 r.push({d:b.d,a:bkeyOf(b.acct),m:b.t=="in"?b.a:-b.a,n:(b.cat?b.cat+": ":"")+b.n,id:b.id})});
return r}
