function saveBk(t){var a=parseFloat(v("f5")),o={id:Date.now(),d:v("f1"),t:t,acct:v("f2"),a:a};
if(!(a>0))return er("Enter an amount above zero.");
if(t=="xfer"){o.to=v("f3");if(o.to==o.acct)return er("Choose two different books.")}else{o.n=v("f4");if(!o.n)return er("Enter the details.");if(t=="out")o.cat=v("f6")}
S.bk.push(o);save();close();renderBook()}
function obForm(){openM('<h2>Opening balances</h2><div class="sub">Money each book held before you started using it</div>'+bookList().map(function(b,i){return '<label>'+esc(b.name)+' (\u20b9)<input id="o'+i+'" inputmode="decimal" value="'+obOf(b.key)+'"></label>'}).join("")+'<div class="err" id="er"></div><div class="row" style="margin-top:14px"><button class="ghost" onclick="close()">Cancel</button><button onclick="saveOb()">Save balances</button></div>')}
