for(var i=0;i<6;i++)rows+='<div class="row"><label>Item<select id="sh'+i+'"><option value="">None</option>'+S.items.map(function(x){return '<option value="'+x.id+'">'+esc(x.name)+' ('+x.stock+' '+esc(x.unit)+' in stock) \u00b7 '+m2(x.sell)+'</option>'}).join("")+'</select></label><label>Qty<input id="sq'+i+'" inputmode="decimal"></label></div>';
