function shopSave(){var L=[],need={};
for(var i=0;i<6;i++){var id=v("sh"+i),q=parseFloat(v("sq"+i));if(!id)continue;if(!(q>0))return er("Enter the quantity for every item chosen.");var it=S.items.filter(function(x){return x.id==id})[0];need[id]=(need[id]||0)+q;var g=it.gst==null?18:it.gst;L.push({item_id:it.id,name:it.name,qty:q,price:it.sell,gst:g,amount:rnd(q*it.sell*(1+g/100)),cost:rnd(q*(it.buy||0))})}
if(!L.length)return er("Choose at least one item.");
for(var k in need){var t=S.items.filter(function(x){return x.id==k})[0];if(need[k]>t.stock)return er("Only "+t.stock+" "+t.unit+" of "+t.name+" in stock.")}
Object.keys(need).forEach(function(k){var t=S.items.filter(function(x){return x.id==k})[0];t.stock=rnd(t.stock-need[k])});
var total=rnd(L.reduce(function(s,x){return s+x.amount},0));
S.shop=S.shop||[];S.shop.push({id:Date.now(),d:bizToday(),mode:v("sm"),lines:L,total:total,note:v("sn")});save();close();renderStock()}
