 if(kind=="advance"||kind=="paid"){S.bk.push({id:Date.now(),d:bizToday(),t:"out",acct:"cash",n:(kind=="advance"?"Advance to ":"Salary paid to ")+(SALNAME[id]||("worker #"+id)),cat:"Salary",ref:"pay:"+r.id,a:amt});save()}
