// ---- Worker's duty export: everything recorded on the duty, with its details
function dutyDoc(d){var pay=d.pay||{},bd=d.breakdown||{},cash=bd.cash||{},sl=bd.slips||{};
var summary=[["Worker",d.worker||""],["Date",fdt(d.d)],["Shift",d.shift||""],["Status",d.status||""],["Litres sold",rnd(d.litres||0)],["Fuel sales",rnd(d.sales||0)],["Lube and shop",rnd(d.lube||0)],["Collected",rnd(d.collected||0)],["Short / excess",rnd(d.diff||0)]];
var lines=(d.lines||[]).map(function(l){return[l.nozzle,l.fuel,l.opening,l.closing,l.testing||0,rnd(l.litres||0),l.rate,rnd(l.amount||0)]});
var modes=Object.keys(pay).map(function(k){return[k,rnd(+pay[k]||0)]});
var notes=Object.keys(cash).filter(function(k){return k!="coins"}).sort(function(a,b){return b-a}).map(function(k){return["\u20b9"+k,cash[k],rnd(k*cash[k])]});if(cash.coins)notes.push(["Coins","",rnd(cash.coins)]);
var slips=[];Object.keys(sl).forEach(function(k){sl[k].forEach(function(x){slips.push([k,x.ref,rnd(x.amt)])})});
var items=(d.items||[]).map(function(i){return[i.name,i.qty,i.price,rnd((+i.qty||0)*(+i.price||0))]});
var exps=(d.expenses||[]).map(function(e){return[e.cat,e.note||"",rnd(e.amount||0)]});
var secs=[{h:"Duty summary",head:["Item","Value"],rows:summary},{h:"Nozzles and readings",head:["Nozzle","Fuel","Opening","Closing","Testing","Litres","Rate","Amount"],rows:lines},{h:"Collected by mode",head:["Mode","Amount"],rows:modes},{h:"Cash count",head:["Note or coin","Count","Amount"],rows:notes},{h:"Payment slips",head:["Mode","Slip / reference","Amount"],rows:slips},{h:"Lube and shop items",head:["Item","Qty","Price","Amount"],rows:items},{h:"Credit sales",head:["Customer","Fuel or item","Litres","Amount","Status"],rows:(d.creditSales||[]).map(function(x){return[x.customer,x.fuel,x.litres||"",x.amount,x.status]})},{h:"Expenses from the till",head:["Category","Details","Amount"],rows:exps},{h:"Note",head:["Note"],rows:[[d.note||""]]}];
return tableDoc("Duty "+(d.shift||"")+" "+fdt(d.d),d.worker||"",secs.filter(function(x){return x.rows.length||x.h=="Duty summary"}))}
