// ---- Theme switcher: colours inspired by major Indian company brands (official brand HEX palettes for BPCL, HPCL, etc.)
var THEMES=[{id:"indigo",name:"Indigo (default)",accent:"#3b5bdb",dark:"#6d8cff"},{id:"indianoil",name:"IndianOil",accent:"#F36C21",accent2:"#003478",dark:"#F36C21",omc:1},{id:"bpcl",name:"BPCL",accent:"#007BC9",accent2:"#FFE000",dark:"#007BC9",omc:1},{id:"hpcl",name:"HPCL",accent:"#00006B",accent2:"#CE0000",dark:"#00006B",omc:1},{id:"nayara",name:"Nayara Energy",accent:"#004282",accent2:"#089C50",dark:"#004282",omc:1},{id:"jiobp",name:"Jio-bp",accent:"#69BE28",accent2:"#0072CE",dark:"#69BE28",omc:1},{id:"shell",name:"Shell",accent:"#FFD500",accent2:"#E31837",dark:"#FFD500",omc:1}];
function themeOf(id){return THEMES.filter(function(t){return t.id==id})[0]||THEMES[0]}
function lumOf(h){var n=parseInt(h.slice(1),16),c=[(n>>16)&255,(n>>8)&255,n&255].map(function(v){v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]}
function contrastOf(a,b){var x=lumOf(a),y=lumOf(b);return (Math.max(x,y)+0.05)/(Math.min(x,y)+0.05)}
function applyTheme(id){var t=themeOf(id),dark=window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches;var c=dark?t.dark:t.accent;var sec=t.accent2||t.accent;var root=document.documentElement.style;
root.setProperty("--accent",c);root.setProperty("--accent-2",sec);root.setProperty("--accent-soft","color-mix(in srgb, "+c+" 14%, transparent)");
// text on the primary: white or near-black, whichever reads better
root.setProperty("--on-accent",contrastOf(c,"#ffffff")>=contrastOf(c,"#111111")?"#ffffff":"#111111");
// focus ring: the primary if it is visible on white, otherwise near-black
root.setProperty("--focus",contrastOf(c,"#ffffff")>=3?c:"#111111");
try{localStorage.setItem("pp-theme",t.id)}catch(e){}}
